value.Compatibilidad:
={{
  (() => {
    const veredicto = $json.veredicto_cto;
    const razonamiento = $json.razonamiento_cto || "";
    const textoCompleto = razonamiento.toLowerCase();

    if (veredicto === "APROBADO") {
      // Si está aprobado, determinamos si es excepcional o media-alta
      if (textoCompleto.includes("excepcional") || textoCompleto.includes("perfecto") || textoCompleto.includes("ideal")) {
        return "Alta (9/10)";
      }
      return "Media-Alta (7/10)";
    } else {
      // Si está rechazado, clasificamos según el nivel de afinidad o motivo
      if (textoCompleto.includes("junior") || textoCompleto.includes("fringe")) {
        return "Media (5/10)";
      }
      if (textoCompleto.includes("senior") || textoCompleto.includes("experiencia")) {
        return "Baja (4/10)";
      }
      return "Baja (2/10)";
    }
  })()
}}

parameters.jsonBody:
{
    "operationName": "PersonalisedCompanies",
    "query": "query PersonalisedCompanies($offset: Int!, $limit: Int!, $companyName: String!, $companySizes: [ID!], $sectorTagPreferences: [SectorTagPreferenceInput!], $investorPreferences: [InvestorPreferenceInput!], $locationPreferences: [Location!], $currency: Currency) {
  personalisedCompanies(
    offset: $offset
    limit: $limit
    companyName: $companyName
    companySizes: $companySizes
    sectorTagPreferences: $sectorTagPreferences
    investorPreferences: $investorPreferences
    locationPreferences: $locationPreferences
  ) {
    id
    urlSafeName
    name
    logoPath
    faviconPath
    primaryColour
    shortDescription
    totalFunding(currency: $currency) {
      amount
      currency
      __typename
    }
    size {
      id
      value
      __typename
    }
    sectorTags {
      id
      value
      __typename
    }
    jobLocations
    brandAssetGroups(groups: [COMPANY_DISCOVERY_PICTURE]) {
      ...SpotlightBrandAssetGroup
      __typename
    }
    __typename
  }
}

fragment BrandAsset on CompanyBrandAsset {
  id
  type
  source
  shortTitle
  longTitle
  category
  alt
  category
  __typename
}

fragment BrandAssetLink on CompanyBrandAssetLink {
  id
  companyBrandAsset {
    ...BrandAsset
    __typename
  }
  mobilePlacement {
    id
    sourceSet(containerWidth: 300)
    source(containerWidth: 300)
    orientation
    width
    __typename
  }
  desktopPlacement {
    id
    sourceSet(containerWidth: 500)
    source(containerWidth: 500)
    orientation
    width
    __typename
  }
  __typename
}

fragment SpotlightBrandAssetGroup on CompanyBrandAssetGroup {
  id
  group {
    id
    name
    __typename
  }
  links {
    ...BrandAssetLink
    __typename
  }
  __typename
}
