const item = $input.first().json;
const titles = item.title || [];
const urls = item.url || [];
const companies = item.company || [];

const results = [];

for (let i = 0; i < titles.length; i++) {
  results.push({
    json: {
      title: titles[i],
      url: urls[i],
      company: companies[i] || "No especificada",
      source: "Tecnoempleo"
    }
  });
}

return results;

// Suponiendo que tu columna se llama "Fecha Enviada Solicitud"
const fechaEnvioStr = $json['Fecha Enviada Solicitud'];

if (!fechaEnvioStr || typeof fechaEnvioStr !== 'string' || !fechaEnvioStr.includes('/')) {
  return { json: { ...$json, diasTranscurridos: 0, enPlazo: false, esGhosting: false } };
}

//Desglosar DD/MM/YYYY
const partes = fechaEnvioStr.trim().split('/');
const dia = parseInt(partes[0], 10);
const mes = parseInt(partes[1], 10) - 1;
let anio = parseInt(partes[2], 10);

if (anio < 100) { anio += 2000 };

const fechaEnvio = new Date(anio, mes, dia);
const hoy = new Date();

//Normalizar a medianoche para contar días naturales
fechaEnvio.setHours(0, 0, 0, 0);
hoy.setHours(0, 0, 0, 0);

const diferenciaMs = hoy.getTime() - fechaEnvio.getTime();
const diasTranscurridos = Math.floor(diferenciaMs / (1000 * 60 * 60 * 24));

//Condición: Entre 2 y 15 días
const enPlazo = diasTranscurridos >=2 && diasTranscurridos < 15;
const esGhosting = diasTranscurridos > 15;

return {
  json: {
    ...$json,
    diasTranscurridos: diasTranscurridos,
    enPlazo: enPlazo,
    esGhosting: esGhosting
  }
};

// Suponiendo que tu columna se llama "Fecha Envío" o similar (formato YYYY-MM-DD o DD/MM/YYYY)
const fechaEnvioStr = $json['Fecha Enviada Solicitud'];

if (!fechaEnvioStr || typeof fechaEnvioStr !== 'string' || !fechaEnvioStr.includes('/')) {
  return { json: { ...$json, diasTranscurridos: 0, esGhosting: false } };
}

//Desglosar DD/MM/YYYY
const partes = fechaEnvioStr.trim().split('/');
const dia = parseInt(partes[0], 10);
const mes = parseInt(partes[1], 10) - 1;
const anio = parseInt(partes[2], 10);

const fechaEnvio = new Date(anio, mes, dia);
const hoy = new Date();

//Normalizar a medianoche para contar días naturales
fechaEnvio.setHours(0, 0, 0, 0);
hoy.setHours(0, 0, 0, 0);

const diferenciaMs = hoy.getTime() - fechaEnvio.getTime();
const diasTranscurridos = Math.floor(diferenciaMs / (1000 * 60 * 60 * 24));

return {
  json: {
    ...$json,
    diasTranscurridos: diasTranscurridos,
    esGhosting: diasTranscurridos >= 15
  }
};
